import manifest from '../lib/images.generated.json';

export type ImageName = keyof typeof manifest;

interface PictureProps {
  name: ImageName;
  alt: string;
  /** The `sizes` attribute: how wide the image renders at each breakpoint. */
  sizes: string;
  className?: string;
  imgClassName?: string;
  /** Above-the-fold images load eagerly with high fetch priority (LCP). */
  priority?: boolean;
}

/**
 * Responsive AVIF/WebP image from public/images/opt (generated by `pnpm images`). Intrinsic
 * width/height are always set so the browser reserves space and nothing shifts on load.
 */
export function Picture({ name, alt, sizes, className, imgClassName, priority }: PictureProps) {
  const { width, height, widths } = manifest[name];
  const srcSet = (format: 'avif' | 'webp') =>
    widths.map((w) => `/images/opt/${name}-${w}.${format} ${w}w`).join(', ');
  const fallback = `/images/opt/${name}-${widths[widths.length - 1] ?? width}.webp`;

  return (
    <picture className={className}>
      <source type="image/avif" srcSet={srcSet('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet('webp')} sizes={sizes} />
      <img
        src={fallback}
        alt={alt}
        width={width}
        height={height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : 'auto'}
        className={imgClassName}
      />
    </picture>
  );
}
